import{_ as o,c as t,a1 as n,o as i}from"./chunks/framework.CnnR69hl.js";const p=JSON.parse('{"title":"Container Networking Documentation Master Prompt","description":"","frontmatter":{},"headers":[],"relativePath":"docker/container-networking-doc-prompt.md","filePath":"docker/container-networking-doc-prompt.md"}'),r={name:"docker/container-networking-doc-prompt.md"};function a(l,e,c,s,d,g){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="container-networking-documentation-master-prompt" tabindex="-1">Container Networking Documentation Master Prompt <a class="header-anchor" href="#container-networking-documentation-master-prompt" aria-label="Permalink to &quot;Container Networking Documentation Master Prompt&quot;">​</a></h1><p>আমি একটা VitePress-based technical documentation website বানাচ্ছি (Bangladeshi developer/DevOps community এর জন্য), এবং এখন <strong>Container Networking (Linux Namespace, veth, Bridge দিয়ে একদম শুরু থেকে)</strong> নিয়ে একটা সম্পূর্ণ, গভীর, hands-on ডকুমেন্টেশন লিখতে চাই। আমি তোমাকে শুধু একটা topic এর নাম দিব, আর তুমি সেই topic নিয়ে সম্পূর্ণ, গভীর documentation page লিখবে।</p><h2 id="এই-ডকুমেন্টেশনের-লক্ষ্য" tabindex="-1">এই ডকুমেন্টেশনের লক্ষ্য <a class="header-anchor" href="#এই-ডকুমেন্টেশনের-লক্ষ্য" aria-label="Permalink to &quot;এই ডকুমেন্টেশনের লক্ষ্য&quot;">​</a></h2><p>Docker/Kubernetes এর container networking আসলে ভিতরে ভিতরে কীভাবে কাজ করে — এটা শেখানো standard Linux command-line tool (<code>ip netns</code>, <code>ip link</code>, <code>iptables</code>) দিয়ে, একদম শূন্য থেকে হাতে-কলমে বানিয়ে। লক্ষ্য: পাঠক যেন বুঝতে পারে Docker-এর <code>bridge</code>/<code>host</code>/<code>none</code> network mode গুলো ভিতরে ভিতরে কী করে, magic মনে না হয়ে।</p><h2 id="writing-style-ও-language" tabindex="-1">Writing Style ও Language <a class="header-anchor" href="#writing-style-ও-language" aria-label="Permalink to &quot;Writing Style ও Language&quot;">​</a></h2><ul><li>সম্পূর্ণ বাংলায় লিখবে, কিন্তু সব technical term (namespace, veth, bridge, NAT, iptables), command, এবং code ইংরেজিতে রাখবে</li><li>প্রতিটা নতুন term প্রথমবার ব্যবহারের সময় সংক্ষেপে বুঝিয়ে দিবে</li><li>Tone friendly কিন্তু professional — senior Linux/container engineer জুনিয়রকে শেখাচ্ছে এমন অনুভূতি</li><li>আমার দেওয়া topic নিয়ে তোমার নিজের জ্ঞান থেকে comprehensive, hands-on-lab-level গভীরতায় লিখবে</li></ul><h2 id="প্রতিটা-topic-এর-জন্য-আবশ্যিক-structure" tabindex="-1">প্রতিটা Topic-এর জন্য আবশ্যিক Structure <a class="header-anchor" href="#প্রতিটা-topic-এর-জন্য-আবশ্যিক-structure" aria-label="Permalink to &quot;প্রতিটা Topic-এর জন্য আবশ্যিক Structure&quot;">​</a></h2><ol><li><strong>What</strong> — জিনিসটা কী, সংক্ষিপ্ত সংজ্ঞা</li><li><strong>Why</strong> — কেন দরকার, container networking-এ এর ভূমিকা কী</li><li><strong>Analogy</strong> — বাস্তব জীবনের উপমা (যেমন: network namespace = আলাদা একটা flat/apartment, bridge = সেই flat গুলোর মধ্যে সংযোগকারী করিডোর/সুইচ)</li><li><strong>Internal Working</strong> — Linux kernel level-এ ভিতরে ভিতরে কী ঘটছে</li><li><strong>Diagram</strong> — Mermaid flowchart/sequenceDiagram দিয়ে network topology, packet flow, বা namespace সংযোগ visualize করবে (এই documentation-এ diagram সবচেয়ে গুরুত্বপূর্ণ অংশ)</li><li><strong>সম্পূর্ণ, চালানোর উপযোগী Command-line Demo</strong> — ধাপে ধাপে (<code>Step 1</code>, <code>Step 2</code>...) প্রতিটা command, এবং command-এর প্রতিটা flag/argument-এর বাংলা ব্যাখ্যা</li><li><strong>Expected Output</strong> — command চালালে বাস্তবে যেমন output আসবে, সেটা দেখানো (<code>ip link list</code>, <code>ip route list</code>, <code>ping</code> output ইত্যাদি বাস্তবসম্মত format-এ)</li><li><strong>Common Failure/Debugging</strong> — এই ধাপে সাধারণত কী কী ভুল হয়, এবং কীভাবে debug করতে হয় (<code>ip route list</code>, <code>ip neigh</code> দিয়ে যাচাই করা)</li><li><strong>Comparison Table</strong> — যেখানে প্রাসঙ্গিক (যেমন veth vs bridge, Docker network mode-গুলোর তুলনা)</li><li><strong>Docker-এর সাথে সংযোগ</strong> — এই Linux-level concept Docker-এর কোন network mode/feature-এর ভিতরে ব্যবহৃত হয়, তা স্পষ্ট করে বলবে</li><li><strong>VitePress Callout</strong> — <code>:::tip</code>, <code>:::warning</code>, <code>:::danger</code> ব্যবহার করবে (বিশেষত root/sudo প্রয়োজন, বা sandbox-এ চালানোর সতর্কতার জন্য)</li><li><strong>Common Mistakes</strong></li><li><strong>Best Practices</strong></li><li><strong>Interview Questions</strong> — ৩-৪টা প্রশ্ন-উত্তর</li><li><strong>Summary</strong></li><li><strong>পরবর্তী ধাপ</strong> — পরের topic-এর দিকে ইঙ্গিত (অন্য file-এর সরাসরি link দিবে না)</li></ol><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ul><li>আমি একটা topic-এর নাম দিব</li><li>তুমি প্রথমে একটা <strong>file name</strong> সাজেস্ট করবে (kebab-case, <code>.md</code> extension সহ)</li><li>তারপর সম্পূর্ণ content লিখবে, উপরের structure মেনে</li><li>সাথে <code>config.mts</code>/<code>config.mjs</code>-এর sidebar entry snippet দিবে (copy-paste করার উপযোগী)</li><li><strong>একবারে একটা topic ই করবে</strong> — আমি &quot;next&quot; না দেওয়া পর্যন্ত এগোবে না</li><li>প্রতিটা topic শেষে জিজ্ঞেস করবে পরের topic-এর জন্য প্রস্তুত কিনা</li></ul><h2 id="content-consistency-—-একটাই-ধারাবাহিক-lab-environment" tabindex="-1">Content Consistency — একটাই ধারাবাহিক Lab Environment <a class="header-anchor" href="#content-consistency-—-একটাই-ধারাবাহিক-lab-environment" aria-label="Permalink to &quot;Content Consistency — একটাই ধারাবাহিক Lab Environment&quot;">​</a></h2><p>পুরো documentation জুড়ে <strong>একই namespace/device নামকরণ convention</strong> ব্যবহার করবে ধারাবাহিকভাবে, যাতে পাঠক একটা লাগাতার lab experience পায়। যেমন <code>netns0</code>, <code>netns1</code>, <code>veth0</code>/<code>ceth0</code>, <code>br0</code>, IP range <code>172.18.0.0/16</code>। একেক topic-এ একেক রকম naming ব্যবহার করবে না।</p><h2 id="suggested-topic-coverage-এই-ক্রমে-দিব" tabindex="-1">Suggested Topic Coverage (এই ক্রমে দিব) <a class="header-anchor" href="#suggested-topic-coverage-এই-ক্রমে-দিব" aria-label="Permalink to &quot;Suggested Topic Coverage (এই ক্রমে দিব)&quot;">​</a></h2><ol><li>Container Networking Fundamentals — Overview (Namespace, veth, Bridge, NAT — সবকিছুর high-level ভূমিকা)</li><li>Linux Network Namespace (netns) — একটা Isolated Network Environment তৈরি করা</li><li>Virtual Ethernet Devices (veth) দিয়ে দুইটা Namespace সংযুক্ত করা</li><li>একাধিক Container/Namespace থাকলে কী সমস্যা হয় (Route Clash) — এবং কেন Bridge দরকার</li><li>Linux Bridge দিয়ে একাধিক Namespace Interconnect করা</li><li>Root Namespace থেকে Container-এ যাওয়া — Bridge-কে IP দেওয়া</li><li>Egress Routing ও NAT (Masquerading) — Container থেকে Internet-এ যাওয়া</li><li>Port Publishing — বাইরের World থেকে Container-এ পৌঁছানো (DNAT)</li><li>Docker Network Driver/Mode ব্যাখ্যা — bridge, host, none (উপরের সবকিছুর সাথে সংযোগ)</li><li>Kubernetes CNI-এর ভূমিকা — Flannel/Calico কেন প্রয়োজন হয় (এই foundation থেকে পরবর্তী ধাপ হিসেবে)</li></ol><h2 id="যা-করবে-না" tabindex="-1">যা করবে না <a class="header-anchor" href="#যা-করবে-না" aria-label="Permalink to &quot;যা করবে না&quot;">​</a></h2><ul><li>আগে থেকে বানানো অন্য কোনো file-এর path/link reference করবে না, যদি না আমি নিশ্চিত করি</li><li>একসাথে একাধিক topic-এর content লিখবে না</li><li>কোনো bash script/command block অসম্পূর্ণ বা partial দিবে না — প্রতিটা demo শুরু থেকে শেষ পর্যন্ত চালানোর উপযোগী হবে</li><li>Content সংক্ষিপ্ত করবে না — একটা hands-on lab tutorial যতটা বিস্তারিত হওয়া উচিত, ততটাই বিস্তারিত হবে</li></ul>',16)])])}const u=o(r,[["render",a]]);export{p as __pageData,u as default};
